# frozen_string_literal: true

# Generated by Torque Lift. Do not edit: Torque Lift regenerates it from torque-lift/tracking-plan.yaml.

# The Torque Lift view helper: `torque_lift_analytics`, put once in each layout right after `<body>`.
#
# It renders the page's route template, the signed-in user and the plan's traits, the visitor's
# consent, and (in production only) the write key and the collector host, then loads the browser
# module from `public/torque_lift/`. The browser sends a page view only after consent.
#
#   <%= torque_lift_analytics(user_id: current_user&.id, consent: analytics_consent) %>
#
# `consent` counts only when it is exactly true.
module TorqueLiftHelper
  def torque_lift_analytics(user_id: nil, consent: false, traits: {})
    production = Rails.env.production?
    pattern = request.respond_to?(:route_uri_pattern) ? request.route_uri_pattern : nil
    kept = traits.to_h.transform_keys(&:to_s).slice(*TorqueLift::IDENTIFY_TRAITS).compact
    nonce = respond_to?(:content_security_policy_nonce) ? content_security_policy_nonce : nil
    element = tag.div(
      id: "torque-lift",
      hidden: true,
      data: {
        route: TorqueLift.route_template(pattern).to_s,
        user: user_id.to_s,
        traits: JSON.generate(kept),
        consent: (consent == true).to_s,
        write_key: production ? ENV.fetch("TORQUELIFT_WRITE_KEY", "") : "",
        host: production ? ENV.fetch("TORQUELIFT_JITSU_HOST", "") : "",
        context: JSON.generate(TorqueLift::GLOBAL_CONTEXT),
        properties: JSON.generate(TorqueLift::GLOBAL_PROPERTIES)
      }
    )
    script = tag.script(type: "module", src: "#{request.script_name}/torque_lift/analytics.boot.js", nonce: nonce)
    safe_join([element, script], "\n")
  end
end
